CREATE FUNCTION public.install_license_signing_key(p_key_id uuid, p_public_jwk jsonb, p_encrypted text, p_iv text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext('adoradrive-license-key')); IF NOT EXISTS (SELECT 1 FROM public.license_signing_keys WHERE key_id = p_key_id) THEN INSERT INTO public.license_verification_keys(id, public_jwk) VALUES(p_key_id, p_public_jwk); INSERT INTO public.license_signing_keys(key_id, encrypted_private_key, encryption_iv) VALUES(p_key_id, p_encrypted, p_iv); END IF; END $$;
REVOKE ALL ON FUNCTION public.install_license_signing_key(uuid, jsonb, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.install_license_signing_key(uuid, jsonb, text, text) TO service_role;